import numpy as np

def softmax(z):
    e = np.exp(z - z.max())
    return e / e.sum()

def grad_log_softmax(z, a):
    g = -softmax(z)
    g[a] += 1.0
    return g

def reinforce(means, steps=2000, lr=0.05, seed=0, baseline=True):
    rng = np.random.default_rng(seed)
    z = np.zeros(len(means)); b = 0.0
    for _ in range(steps):
        probs = softmax(z)
        a = rng.choice(len(means), p=probs)
        r = rng.normal(means[a], 1)
        A = r - b if baseline else r
        z += lr * A * grad_log_softmax(z, a)
        b += 0.01 * (r - b)
    return softmax(z)

