problems.solution:
import numpy as np

def ppo_objective(ratio, adv, eps=0.2):
    ratio = np.asarray(ratio, dtype=float); adv = np.asarray(adv, dtype=float)
    clipped = np.clip(ratio, 1 - eps, 1 + eps)
    return float(np.minimum(ratio * adv, clipped * adv).mean())
